import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    start = 0
    while start < len(records) - 1 and not any(cell.strip() for cell in records[start]):
        start += 1

    if start + 2 < len(records):
        first = records[start]
        candidate = records[start + 1]
        first_nonempty = sum(bool(cell.strip()) for cell in first)
        candidate_text = sum(
            bool(cell.strip()) and any(char.isalpha() for char in cell)
            for cell in candidate
        )
        if first_nonempty == 1 and candidate_text >= 2:
            start += 1

    columns = list(records[start])
    rows = records[start + 1:]
    width = max([len(columns)] + [len(row) for row in rows])

    used = set(columns)
    while len(columns) < width:
        base = "column_" + str(len(columns) + 1)
        name = base
        suffix = 2
        while name in used:
            name = base + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        used.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
